"use client";

import { useState } from "react";
import { createClient } from "@/utils/supabase/client";
import {
  RefreshCw,
  CheckCircle2,
  Lock,
  Terminal,
  ShieldCheck,
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

interface AccessRequest {
  email: string;
  status: string;
  date: string;
}

export default function AdminPanel() {

  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [requests, setRequests] = useState<AccessRequest[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const handleLogin = async () => {


    try {

      const supabase = createClient();

      const {
        data:{session}
      } = await supabase.auth.getSession();


      if(!session){
        alert("Identity session required");
        return;
      }


      setIsAuthenticated(true);

      await fetchRequests();


    } catch(error){

      console.error(
        "Identity authentication failed:",
        error
      );

    }

  };

  const fetchRequests = async () => {
    setIsLoading(true);
    try {
      const res = await fetch("/api/early-access");
      const data = await res.json();
      setRequests(data);
    } catch (error) {
      console.error("Failed to fetch requests:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogout = async () => {
    try {
      await fetch("/api/early-access", {
        method: "DELETE",
      });
    } finally {
      const supabase = createClient();
      await supabase.auth.signOut();
      setIsAuthenticated(false);
    }
  };

  const approveUser = async (email: string) => {
    try {
      const res = await fetch("/api/early-access", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          email,
          action: "approve",
        }),
      });
      const data = await res.json();
      if (data.success) {
        setRequests(data.requests);
      }
    } catch (error) {
      console.error("Failed to approve user:", error);
    }
  };

  // 1. Durum: Kimlik DoÄŸrulama (Login) EkranÄ±
  if (!isAuthenticated) {
    return (
      <main className="min-h-screen bg-zinc-950 text-white flex flex-col items-center justify-center px-6 font-sans relative overflow-hidden selection:bg-blue-500/30">
        {/* Arkaplan IÅŸÄ±k Efekti */}
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[800px] h-[400px] bg-[radial-gradient(ellipse_at_top,rgba(0,102,238,0.15)_0%,transparent_70%)] pointer-events-none" />

        <motion.form
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          onSubmit={handleLogin}
          className="relative z-10 bg-zinc-900/60 backdrop-blur-2xl border border-zinc-800 p-8 sm:p-10 rounded-[2rem] max-w-sm w-full space-y-8 shadow-[0_25px_60px_rgba(0,0,0,0.6)]"
        >
          <div className="flex flex-col items-center text-center space-y-3">
            <div className="w-14 h-14 rounded-2xl bg-blue-500/10 border border-blue-500/20 flex items-center justify-center text-blue-400 mb-2 shadow-inner">
              <Lock className="w-6 h-6" />
            </div>
            <h1 className="text-2xl font-serif tracking-tight text-white">
              Secure Gateway
            </h1>
            <p className="text-[11px] font-mono text-zinc-400 leading-relaxed uppercase tracking-widest">
              Aegisora Command Center
            </p>
          </div>

          <div className="space-y-5">
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Terminal className="w-4 h-4 text-zinc-500" />
              </div>

            </div>
            <button
              type="submit"
              className="w-full bg-blue-600 hover:bg-blue-500 text-white py-3.5 rounded-xl text-xs font-mono font-medium transition-all shadow-lg shadow-blue-600/20 cursor-pointer outline-none flex items-center justify-center gap-2"
            >
              <span>Authenticate</span>
              <ShieldCheck className="w-4 h-4" />
            </button>
          </div>
        </motion.form>

        {/* Alt GÃ¼venlik Bildirimi */}
        <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-2 text-[10px] font-mono text-zinc-600 tracking-widest uppercase">
          <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
          End-to-end encrypted connection
        </div>
      </main>
    );
  }

  // 2. Durum: YÃ¶netim Paneli (Dashboard) EkranÄ±
  return (
    <main className="min-h-screen bg-zinc-950 text-white p-6 md:p-12 font-sans relative overflow-hidden selection:bg-blue-500/30">
      {/* Arkaplan IÅŸÄ±k Efekti */}
      <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[1200px] h-[500px] bg-[radial-gradient(ellipse_at_top,rgba(0,102,238,0.1)_0%,transparent_70%)] pointer-events-none" />

      <div className="max-w-[1000px] mx-auto space-y-8 relative z-10 pt-8">
        {/* Header AlanÄ± */}
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-end border-b border-zinc-800/80 pb-6 gap-6">
          <div>
            <span className="text-[10px] font-mono font-semibold uppercase tracking-widest text-blue-400 bg-blue-950/60 border border-blue-800/40 px-3 py-1 rounded-full mb-4 inline-block">
              Root Access
            </span>
            <h1 className="text-3xl md:text-4xl font-serif tracking-tight text-white mb-2">
              Command Center
            </h1>
            <p className="text-zinc-400 text-xs font-mono">
              Monitor, manage, and approve early access sandbox deployment
              requests.
            </p>
          </div>
          <button
            onClick={fetchRequests}
            disabled={isLoading}
            className="bg-zinc-900/80 hover:bg-zinc-800 border border-zinc-700 text-white text-[11px] font-mono px-4 py-2.5 rounded-xl flex items-center gap-2 cursor-pointer transition-colors outline-none shadow-sm"
          >
            <RefreshCw
              className={`w-3.5 h-3.5 text-blue-400 ${isLoading ? "animate-spin" : ""}`}
            />
            <span>Refresh Telemetry</span>
          </button>
        </div>

        {/* Tablo AlanÄ± */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-zinc-900/40 backdrop-blur-xl border border-zinc-800 rounded-[2rem] overflow-hidden shadow-2xl"
        >
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="border-b border-zinc-800 text-zinc-500 text-[10px] font-mono uppercase tracking-widest bg-zinc-950/50">
                  <th className="p-5 font-medium">Identity / Email</th>
                  <th className="p-5 font-medium">Clearance Status</th>
                  <th className="p-5 font-medium">Timestamp</th>
                  <th className="p-5 font-medium text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="font-mono text-xs">
                {requests.length === 0 ? (
                  <tr>
                    <td
                      colSpan={4}
                      className="p-16 text-center flex flex-col items-center justify-center space-y-3"
                    >
                      <Terminal className="w-6 h-6 text-zinc-700" />
                      <span className="text-zinc-500 text-[11px] uppercase tracking-widest">
                        Awaiting network requests...
                      </span>
                    </td>
                  </tr>
                ) : (
                  <AnimatePresence>
                    {requests.map((req, idx) => (
                      <motion.tr
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        key={idx}
                        className="border-b border-zinc-800/50 hover:bg-zinc-800/30 transition-colors group"
                      >
                        <td className="p-5 text-zinc-300 font-medium">
                          {req.email}
                        </td>
                        <td className="p-5">
                          <span
                            className={`inline-flex items-center gap-2 px-3 py-1 rounded-full text-[10px] font-semibold uppercase tracking-widest ${
                              req.status === "approved"
                                ? "bg-emerald-950/40 text-emerald-400 border border-emerald-800/30"
                                : "bg-amber-950/40 text-amber-400 border border-amber-800/30"
                            }`}
                          >
                            <span
                              className={`w-1.5 h-1.5 rounded-full ${req.status === "approved" ? "bg-emerald-400 shadow-[0_0_8px_#34d399]" : "bg-amber-400 shadow-[0_0_8px_#fbbf24] animate-pulse"}`}
                            />
                            {req.status}
                          </span>
                        </td>
                        <td className="p-5 text-zinc-500">
                          {new Date(req.date).toLocaleString("en-US", {
                            month: "short",
                            day: "numeric",
                            year: "numeric",
                            hour: "numeric",
                            minute: "2-digit",
                          })}
                        </td>
                        <td className="p-5 text-right">
                          {req.status !== "approved" ? (
                            <button
                              onClick={() => approveUser(req.email)}
                              className="bg-blue-600/10 hover:bg-blue-600 hover:text-white text-blue-400 border border-blue-600/30 text-[10px] font-mono font-medium px-4 py-2 rounded-full transition-all shadow-sm cursor-pointer outline-none inline-flex items-center gap-1.5 uppercase tracking-widest"
                            >
                              <CheckCircle2 className="w-3.5 h-3.5" />
                              <span>Authorize</span>
                            </button>
                          ) : (
                            <span className="text-zinc-600 text-[10px] uppercase tracking-widest font-semibold px-4 py-2 inline-flex items-center gap-1.5">
                              <ShieldCheck className="w-3.5 h-3.5" />
                              Active
                            </span>
                          )}
                        </td>
                      </motion.tr>
                    ))}
                  </AnimatePresence>
                )}
              </tbody>
            </table>
          </div>
        </motion.div>
      </div>
    </main>
  );
}

import { NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { requireUser } from "@/utils/supabase/auth-guard";

// Tip Tanımlamaları
interface Message {
  role: "user" | "assistant" | "system";
  content: string;
}

interface GroqRequestPayload {
  messages: Message[];
}

export async function POST(req: Request) {
  try {
    const rawBody = await req.text();
    console.log("[CHAT RAW BODY]", rawBody);
    const body: GroqRequestPayload = JSON.parse(rawBody);
    const messages = body.messages;

    if (!messages || !Array.isArray(messages)) {
      return NextResponse.json(
        { error: "Invalid request payload: 'messages' array is required." },
        { status: 400 },
      );
    }

    const groqApiKey = process.env.GROQ_API_KEY;
    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
    const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

    if (!groqApiKey || !supabaseUrl || !supabaseServiceKey) {
      console.error("[Aegisora Core] Missing critical environment variables.");
      return NextResponse.json(
        {
          error: "Server configuration error. Contact platform administrator.",
        },
        { status: 500 },
      );
    }

    // ?? Server-side Supabase Client (Enterprise Güvenlik Optimizasyonu)
    // Sadece sunucu tarafında çalışan ve RLS'i bypass eden Service Role Key kullanıyoruz.
    const supabase = createClient(supabaseUrl, supabaseServiceKey, {
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    });

    // ?? Veritabanından Anlık Enterprise Telemetri Verilerini Çekelim
    let dbContextSummary = "No active database context available.";
    try {
      const [agentsRes, incidentsRes, policiesRes] = await Promise.all([
        supabase.from("agents").select("id, name, model, risk_level, status"),
        supabase
          .from("incidents")
          .select("id, threat_type, severity, status, agent_name")
          .order("created_at", { ascending: false })
          .limit(5),
        supabase.from("policy_rules").select("policy_key, is_enabled"),
      ]);

      // Hata kontrolü
      if (agentsRes.error)
        console.error("Agents fetch error:", agentsRes.error);
      if (incidentsRes.error)
        console.error("Incidents fetch error:", incidentsRes.error);
      if (policiesRes.error)
        console.error("Policies fetch error:", policiesRes.error);

      dbContextSummary = `
REAL-TIME DATABASE TELEMETRY & STATE:
- Total Deployed Agents: ${agentsRes.data?.length || 0}
- Agent Fleet Details: ${JSON.stringify(agentsRes.data || [])}
- Recent Security Incidents: ${JSON.stringify(incidentsRes.data || [])}
- Active Security Policies: ${JSON.stringify(policiesRes.data || [])}
`;
    } catch (dbErr) {
      console.error(
        "[Aegisora Core] Failed to fetch DB context for AI telemetry:",
        dbErr,
      );
    }

    // ?? Groq API Çağrısı
    const response = await fetch(
      "https://api.groq.com/openai/v1/chat/completions",
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${groqApiKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          model: "openai/gpt-oss-120b",
          messages: [
            {
              role: "system",
              content: `You are Aegisora Intelligence Core, an expert enterprise AI security, governance, and runtime protection assistant.
You have direct, real-time access to the organization's PostgreSQL database telemetry.

${dbContextSummary}

Guidelines:
- Always base your security answers, analytics, and diagnostics on the real database telemetry provided above. Never invent fake agent names or mock incident IDs if real ones exist.
- If the user asks about the fleet, incidents, or security rules, quote the actual data from the telemetry above.
- If you need clarification or want to give the user quick choices to narrow down their request (like interactive options), you MUST include a JSON block at the very end of your response formatted exactly like this:
\`\`\`json
{
  "options": ["Option 1", "Option 2", "Option 3"]
}
\`\`\`
If no choices are needed, do not include this json block. Be professional, technical, precise, and authoritative.`,
            },
            ...messages,
          ],
          temperature: 0.3,
          max_tokens: 1024,
        }),
      },
    );

    const data = await response.json();

    if (!response.ok) {
      throw new Error(
        data.error?.message || "Failed to communicate with Groq API.",
      );
    }

    const rawContent =
      data.choices?.[0]?.message?.content || "No response generated.";

    // ??? JSON Parse Optimizasyonu
    let options: string[] = [];
    let cleanContent = rawContent;

    const jsonMatch = rawContent.match(/```json\s*([\s\S]*?)\s*```/);
    if (jsonMatch) {
      try {
        const parsed = JSON.parse(jsonMatch[1]);
        if (parsed && Array.isArray(parsed.options)) {
          options = parsed.options;
        }
        cleanContent = rawContent.replace(jsonMatch[0], "").trim();
      } catch (parseError) {
        console.warn(
          "[Aegisora Core] Failed to parse JSON options from LLM response:",
          parseError,
        );
        // Parse hatası olursa içeriği bozmamak için müdahale etmiyoruz
      }
    }

    return NextResponse.json({ result: cleanContent, options });
  } catch (error: unknown) {
    console.error("[Aegisora Core] API Route Error:", error);
    return NextResponse.json(
      { error: "Internal Server Error during AI processing." },
      { status: 500 },
    );
  }
}

import { NextResponse } from "next/server";
import { requireAdmin } from "@/utils/supabase/auth-guard";
import { writeAuditLog } from "@/utils/audit/audit-log";
import { rateLimit } from "@/utils/security/rate-limit";
import { revokeSession } from "@/utils/security/session-revocation";

interface EarlyAccessRequest {
  email:string;
  status:"pending"|"approved";
  date:string;
}

declare global {
  var _earlyAccessRequests: EarlyAccessRequest[] | undefined;
}

if(!global._earlyAccessRequests){
  global._earlyAccessRequests=[];
}

const requests=global._earlyAccessRequests;


export async function GET(request:Request){

  const ip =
    request.headers.get("x-forwarded-for") ??
    "unknown";


  if(!rateLimit(ip)){
    return NextResponse.json(
      {
        error:"Too many requests"
      },
      {
        status:429
      }
    );
  }

  try{

    const admin=await requireAdmin();

    if(!admin){
      return NextResponse.json(
        {error:"Unauthorized"},
        {status:401}
      );
    }


    const {searchParams}=new URL(request.url);

    const email=searchParams.get("email");


    if(email){

      const found=requests.find(
        r=>r.email===email
      );

      return NextResponse.json({
        exists:!!found,
        status:found?.status ?? "none"
      });

    }


    return NextResponse.json(requests);


  }catch(error){

    console.error(
      "Early Access GET Error:",
      error
    );

    return NextResponse.json(
      {error:"Server error"},
      {status:500}
    );
  }

}



export async function POST(request:Request){

  const ip =
    request.headers.get("x-forwarded-for") ??
    "unknown";


  if(!rateLimit(ip)){
    return NextResponse.json(
      {
        error:"Too many requests"
      },
      {
        status:429
      }
    );
  }

  try{


    const body=await request.json();

    const {
      email,
      action
    }=body;



    if(action==="approve"){

      const admin=await requireAdmin();


      if(!admin){

        return NextResponse.json(
          {error:"Unauthorized"},
          {status:401}
        );

      }


      const target=requests.find(
        r=>r.email===email
      );


      if(target){

        target.status="approved";

      }else{

        requests.push({
          email,
          status:"approved",
          date:new Date().toISOString()
        });

      }


      await writeAuditLog(
        "APPROVE_EARLY_ACCESS",
        {
          email,
          adminId: admin.id
        }
      );

      return NextResponse.json({
        success:true,
        requests
      });

    }



    if(!email || typeof email!=="string"){

      return NextResponse.json(
        {error:"Valid email required"},
        {status:400}
      );

    }



    const existing=requests.find(
      r=>r.email===email
    );


    if(!existing){

      requests.push({

        email,

        status:"pending",

        date:new Date().toISOString()

      });

    }



    return NextResponse.json({

      success:true,

      status:
        existing?.status ?? "pending"

    });



  }catch(error){

    console.error(
      "Early Access POST Error:",
      error
    );


    return NextResponse.json(
      {error:"Server error"},
      {status:500}
    );

  }

}

export async function DELETE(request: Request) {
  try {
    const supabase = await (await import("@/utils/supabase/server")).createClient();

    const {
      data: { session },
    } = await supabase.auth.getSession();

    if (!session?.access_token) {
      return NextResponse.json(
        { error: "No active session" },
        { status: 401 }
      );
    }

    await revokeSession(session.access_token);
    await supabase.auth.signOut();

    return NextResponse.json({
      success: true,
      revoked: true,
    });
  } catch (error) {
    console.error("Admin session revoke failed:", error);

    return NextResponse.json(
      { error: "Session revocation failed" },
      { status: 500 }
    );
  }
}

