"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import { useRouter } from "next/navigation";

export default function EarlyAccessPage() {
  const [email, setEmail] = useState("");
  const [loading, setLoading] = useState(false);
  const [statusMessage, setStatusMessage] = useState<string | null>(null);
  const router = useRouter();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) return;

    setLoading(true);
    setStatusMessage(null);

    try {
      const res = await fetch("/api/early-access", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email }),
      });

      const data = await res.json();

      if (data.success) {
        if (data.status === "approved") {
          localStorage.setItem("aegisora_user_email", email);
          router.push("/early-access/sandbox");
        } else {
          setStatusMessage(
            "Request received! Your access is pending Eray's admin approval.",
          );
        }
      }
    } catch (error) {
      setStatusMessage("An error occurred. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <main className="min-h-screen bg-black text-white flex flex-col items-center justify-center px-6 relative overflow-hidden font-sans">
      <div className="absolute w-[500px] h-[500px] bg-blue-600/10 rounded-full blur-[120px] pointer-events-none" />

      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
        className="max-w-xl w-full bg-zinc-900/50 border border-zinc-800 p-8 rounded-2xl backdrop-blur-xl relative z-10 shadow-2xl"
      >
        <div className="text-center mb-8">
          <span className="text-xs uppercase tracking-widest text-blue-400 font-semibold font-mono bg-blue-950/40 px-3 py-1 rounded-full border border-blue-800/50">
            Core Contributor Program
          </span>
          <h1 className="text-3xl font-serif mt-4 tracking-tight">
            Aegisora Early Access & Sandbox
          </h1>
          <p className="text-zinc-400 text-sm mt-2 font-mono leading-relaxed">
            Shape the future of autonomous AI governance. Enter your
            professional email to request secure access.
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-medium text-zinc-300 mb-1 font-mono">
              Professional / Work Email
            </label>
            <input
              type="email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="name@company.com or university.de"
              className="w-full bg-black/50 border border-zinc-800 rounded-xl px-4 py-3 text-xs font-mono text-white focus:outline-none focus:border-[#0066EE] transition-colors placeholder-zinc-600"
            />
          </div>
          <button
            type="submit"
            disabled={loading}
            className="w-full bg-[#0066EE] hover:bg-[#005bb5] text-white font-medium py-3 rounded-xl transition-colors text-xs font-mono tracking-wide disabled:opacity-50 cursor-pointer outline-none shadow-sm flex items-center justify-center"
          >
            {loading ? "Checking..." : "Request Secure Access"}
          </button>
        </form>

        {statusMessage && (
          <div className="mt-6 p-4 bg-amber-950/30 border border-amber-800/40 rounded-xl text-center text-amber-400 text-xs font-mono">
            {statusMessage}
          </div>
        )}
      </motion.div>
    </main>
  );
}

"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { useRouter } from "next/navigation";

export default function ContributorSandbox() {
  const [authorized, setAuthorized] = useState(false);
  const [loading, setLoading] = useState(true);
  const router = useRouter();

  const [activeTab, setActiveTab] = useState("pipelines");
  const [testStatus, setTestStatus] = useState<"idle" | "running" | "success">(
    "idle",
  );
  const [proposal, setProposal] = useState("");
  const [submittedProposal, setSubmittedProposal] = useState(false);

  useEffect(() => {
    const email = localStorage.getItem("aegisora_user_email");
    if (!email) {
      router.push("/early-access");
      return;
    }

    fetch(`/api/early-access?email=${email}`)
      .then((res) => res.json())
      .then((data) => {
        if (data.status === "approved") {
          setAuthorized(true);
        } else {
          alert("Your access is still pending admin approval by Eray.");
          router.push("/early-access");
        }
        setLoading(false);
      })
      .catch(() => {
        router.push("/early-access");
      });
  }, [router]);

  const runTestPipeline = () => {
    setTestStatus("running");
    setTimeout(() => {
      setTestStatus("success");
    }, 1500);
  };

  const handleProposalSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!proposal) return;
    setSubmittedProposal(true);
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-black text-white flex items-center justify-center text-sm font-mono">
        Verifying secure clearance node...
      </div>
    );
  }

  if (!authorized) return null;

  return (
    <main className="min-h-screen bg-black text-white p-6 md:p-12 font-sans">
      <div className="max-w-6xl mx-auto space-y-8">
        {/* Üst Bilgi / Header */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center border-b border-zinc-800 pb-6 gap-4">
          <div>
            <div className="flex items-center gap-2">
              <span className="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse" />
              <span className="text-xs uppercase tracking-widest text-emerald-400 font-semibold font-mono">
                Core Contributor Environment Active
              </span>
            </div>
            <h1 className="text-2xl md:text-3xl font-serif mt-2 tracking-tight">
              Aegisora Agent Governance Sandbox
            </h1>
            <p className="text-zinc-400 text-sm font-mono mt-1">
              Test your multi-agent pipelines against enterprise compliance
              frameworks (EU DSA & GDPR).
            </p>
          </div>
          <div className="bg-zinc-900 border border-zinc-800 px-4 py-2 rounded-xl text-xs text-zinc-300 font-mono">
            Node:{" "}
            <span className="text-blue-400 font-mono">eu-central-trier-01</span>
          </div>
        </div>

        {/* Sekmeler */}
        <div className="flex gap-6 border-b border-zinc-800 text-sm font-medium">
          <button
            onClick={() => setActiveTab("pipelines")}
            className={`pb-3 transition-colors border-b-2 outline-none cursor-pointer ${
              activeTab === "pipelines"
                ? "border-white text-white"
                : "border-transparent text-zinc-400 hover:text-white"
            }`}
          >
            Agent Pipelines & Audit
          </button>
          <button
            onClick={() => setActiveTab("governance")}
            className={`pb-3 transition-colors border-b-2 outline-none cursor-pointer ${
              activeTab === "governance"
                ? "border-white text-white"
                : "border-transparent text-zinc-400 hover:text-white"
            }`}
          >
            Governance Rules (EU DSA)
          </button>
          <button
            onClick={() => setActiveTab("propose")}
            className={`pb-3 transition-colors border-b-2 outline-none cursor-pointer ${
              activeTab === "propose"
                ? "border-white text-white"
                : "border-transparent text-zinc-400 hover:text-white"
            }`}
          >
            Shape Core Architecture 💡
          </button>
        </div>

        {/* İçerik Alanı 1: Pipelines */}
        {activeTab === "pipelines" && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="bg-zinc-900/50 border border-zinc-800 p-6 rounded-2xl space-y-4">
              <h3 className="font-semibold text-base">
                Run Compliance Simulation
              </h3>
              <p className="text-xs text-zinc-400 font-mono leading-relaxed">
                Execute a sample multi-agent RAG workflow through
                Aegisora&apos;s Zero-Trust proxy layer.
              </p>
              <div className="bg-black/40 border border-zinc-800 p-3 rounded-xl font-mono text-xs text-zinc-300 space-y-1">
                <div>
                  Target: <span className="text-blue-400">LLM-Gateway-v2</span>
                </div>
                <div>
                  Shields: <span className="text-emerald-400">Active</span>
                </div>
                <div>
                  Compliance:{" "}
                  <span className="text-amber-400">EU-DSA-Strict</span>
                </div>
              </div>
              <button
                onClick={runTestPipeline}
                disabled={testStatus === "running"}
                className="w-full bg-[#0066EE] hover:bg-[#005bb5] text-white font-medium py-3 rounded-xl transition-colors text-xs font-mono disabled:opacity-50 cursor-pointer outline-none shadow-sm"
              >
                {testStatus === "running"
                  ? "Evaluating Agents..."
                  : "Run Pipeline Test"}
              </button>
            </div>

            <div className="lg:col-span-2 bg-zinc-900/50 border border-zinc-800 p-6 rounded-2xl flex flex-col justify-between">
              <div>
                <h3 className="font-semibold text-base mb-4">
                  Real-time Governance Stream
                </h3>
                <div className="bg-black/60 border border-zinc-800 p-4 rounded-xl font-mono text-xs text-zinc-400 h-48 overflow-y-auto space-y-2">
                  <div className="text-zinc-500">
                    [System] Initializing sandbox environment for contributor...
