            >
              {/* Drawer Header */}
              <div className="flex items-start justify-between p-6 border-b border-slate-200 dark:border-white/10 bg-slate-50/50 dark:bg-transparent">
                <div>
                  <h2 className="text-[24px] font-bold text-slate-900 dark:text-white mb-2">{selectedPolicy.title}</h2>
                  <div className="flex items-center gap-4 text-[13px] text-slate-500">
                    <span className="flex items-center gap-1.5 px-2 py-1 rounded-full bg-slate-100 dark:bg-white/5"><History className="w-3 h-3"/> v{selectedPolicy.version}</span>
                    <Link href="#" className="flex items-center gap-1.5 hover:text-blue-600 transition-colors"><GithubIcon className="w-4 h-4" /> View Source</Link>
                  </div>
                </div>
                <button onClick={() => setSelectedPolicy(null)} className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-white/5 text-slate-400 transition-colors">
                  <X className="w-6 h-6" />
                </button>
              </div>

              {/* Drawer Body */}
              <div className="flex-1 overflow-y-auto p-6 space-y-8">

                {/* Two Column Layout for Details */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                  <div className="md:col-span-2 space-y-6">
                    <div>
                      <h3 className="text-[14px] font-bold text-slate-900 dark:text-white mb-2">Description</h3>
                      <p className="text-[14px] text-slate-600 dark:text-slate-400 leading-relaxed">{selectedPolicy.desc}</p>
                    </div>
                    <div>
                      <h3 className="text-[14px] font-bold text-slate-900 dark:text-white mb-2">Intended Use</h3>
                      <p className="text-[14px] text-slate-600 dark:text-slate-400 leading-relaxed">
                        This validator should be used whenever an input prompt to an LLM is susceptible to prompt injection. It relies on a secondary model to score the prompt and uses a threshold to block malicious attempts.
                      </p>
