                  {/* Meta Sidebar */}
                  <div className="space-y-4 text-[13px] border-l border-slate-200 dark:border-white/10 pl-6">
                    <div>
                      <div className="text-slate-400 mb-1">Developed By</div>
                      <div className="font-semibold text-slate-900 dark:text-white">{selectedPolicy.author}</div>
                    </div>
                    <div>
                      <div className="text-slate-400 mb-1">Validator Type</div>
                      <div className="font-semibold text-slate-900 dark:text-white">{selectedPolicy.category}</div>
