                <div>
                  <h3 className="text-[16px] font-bold text-slate-900 dark:text-white mb-3 flex items-center gap-2"><Download className="w-4 h-4"/> Install</h3>
                  <div className="relative group">
                    <pre className="p-4 rounded-xl bg-slate-900 text-slate-300 font-mono text-[13px] overflow-x-auto border border-slate-800">
                      <code>{selectedPolicy.command}</code>
